create table outbox_event (intentos integer not null, fecha_creacion timestamp(6) not null, id bigint generated by default as identity, producto_id bigint not null, estado varchar(255) not null check ((estado in ('PENDIENTE','ENVIADO','ERROR'))), tipo_evento varchar(255) not null check ((tipo_evento in ('CREACION'))), primary key (id));
create table producto (precio numeric(12,2) not null, fecha_creacion timestamp(6) not null, id bigint generated by default as identity, version bigint not null, nombre varchar(150) not null, descripcion varchar(1000), imagen_url varchar(2000), estado varchar(20) default 'ACTIVO' not null check ((estado in ('PENDIENTE','ACTIVO','BAJA'))), primary key (id));
